// Generated by build.mjs from @space/glyph-art (src/draw.mjs). Do not edit.
(() => {
// Browser half of the glyph art: draws a grid from generate.mjs onto a canvas as 0s and 1s, the subject centred on two rows of
// "ground". Plain ESM with no imports, so the React app imports it and the dependency-free halmic build copies it into public/.
//
// The canvas is laid out by CSS (full width of its box; height from --gw and --gh, see ROWS_AROUND) and this only paints it.

/** Rows drawn besides the subject's own: one above it, two of ground below. */
const ROWS_AROUND = 3
const CELL = 0.6

// A cell's digit: a fixed hash of its position, so the art is the same on every load and has no visible stripes.
function bit(x, y) {
  let h = Math.imul(x + 1, 0x9e3779b1) ^ Math.imul(y + 1, 0x85ebca77)
  h ^= h >>> 15
  h = Math.imul(h, 0x2c1b3c6d)
  h ^= h >>> 12
  return (h >>> 3) & 1 ? '1' : '0'
}

/**
 * Paints `grid` into `canvas` at the canvas's CSS size.
 * opts.dark: light glyphs for a dark page (lightness range and ground strength follow it).
 * opts.ground: CSS colour of the ground rows. opts.font: a CSS font-family list (a monospace face).
 */
function drawGlyphs(canvas, grid, { dark = false, ground = 'currentColor', font = 'ui-monospace, monospace', maxFont = 10 } = {}) {
  const ctx = canvas.getContext('2d')
  if (!ctx) return
  const cssW = canvas.clientWidth
  const cssH = canvas.clientHeight
  if (!cssW || !cssH) return
  const dpr = Math.min(window.devicePixelRatio || 1, 2)
  canvas.width = Math.round(cssW * dpr)
  canvas.height = Math.round(cssH * dpr)
  const fs = Math.min(maxFont, cssW / (grid.w * CELL))
  const cw = fs * CELL
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0)
  ctx.clearRect(0, 0, cssW, cssH)
  ctx.font = `${fs}px ${font}`
  ctx.textBaseline = 'top'
  ctx.textAlign = 'center'
  const [lo, hi] = dark ? [0.5, 0.93] : [0.3, 0.68]
  const ox = (cssW - grid.w * cw) / 2
  for (let y = 0; y < grid.h; y++)
    for (let x = 0; x < grid.w; x++) {
      const i = y * grid.w + x
      const p = grid.c[i]
      if (p === ' ') continue
      const [C, h] = grid.pal[p.charCodeAt(0) - 97]
      const L = lo + (hi - lo) * (Number(grid.l[i]) / 9)
      ctx.fillStyle = `oklch(${L.toFixed(3)} ${Math.min(0.17, C * 1.25).toFixed(3)} ${h})`
      ctx.fillText(bit(x, y), ox + x * cw + cw / 2, (y + 1) * fs)
    }
  // ground: the full width of the canvas, the first row stronger
  const cols = Math.ceil(cssW / cw)
  ctx.fillStyle = ground
  for (let r = 0; r < 2; r++) {
    ctx.globalAlpha = (dark ? [0.55, 0.28] : [0.6, 0.3])[r]
    for (let x = 0; x < cols; x++) ctx.fillText(bit(x, grid.h + r + 7), x * cw + cw / 2, (grid.h + 1 + r) * fs)
  }
  ctx.globalAlpha = 1
}

const box = document.currentScript.previousElementSibling;
const grid = JSON.parse(box.querySelector('script').textContent);
const cv = box.querySelector('canvas');
box.style.setProperty('--gw', grid.w);
box.style.setProperty('--gh', grid.h + ROWS_AROUND);
const paint = () => drawGlyphs(cv, grid, { dark: true, ground: getComputedStyle(box).getPropertyValue('--blue-live').trim(), font: 'ui-monospace, SFMono-Regular, Menlo, Consolas, monospace' });
paint();
new ResizeObserver(paint).observe(cv);
document.fonts?.ready.then(paint);
})();
